module sort_minimum_swaps(\n    input clk, rst_n, start,\n    input [7:0] initial_perm,\n    input [23:0] swaps,\n    input [2:0] num_swaps,\n    output reg [4:0] min_swaps,\n    output reg done,\n    output reg error\n);\n    localparam [2:0] STATE_IDLE = 3'd0;\n    localparam [2:0] STATE_INIT = 3'd1;\n    localparam [2:0] STATE_DEQUEUE = 3'd2;\n    localparam [2:0] STATE_CHECK = 3'd3;\n    localparam [2:0] STATE_PROCESS_SWAP = 3'd4;\n    localparam [2:0] STATE_NEXT_SWAP = 3'd5;\n    localparam [2:0] STATE_DONE = 3'd6;\n    localparam [2:0] STATE_ERROR = 3'd7;\n\n    reg [2:0] current_state, next_state;\n    reg [7:0] current_perm, new_perm;\n    reg [4:0] distance_reg;\n    reg [2:0] swap_counter;\n    reg [255:0] visited;\n    reg [7:0] queue [0:23];\n    reg [4:0] dist_queue [0:23];\n    reg [4:0] head, tail;\n    reg [4:0] min_swaps_reg;\n    wire fifo_empty;\n    integer i;\n\n    assign fifo_empty = (head == tail);\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            current_state <= STATE_IDLE;\n            min_swaps <= 5'd0;\n            done <= 1'b0;\n            error <= 1'b0;\n            distance_reg <= 5'd0;\n            swap_counter <= 3'd0;\n            head <= 5'd0;\n            tail <= 5'd0;\n            visited <= 256'd0;\n            current_perm <= 8'd0;\n            min_swaps_reg <= 5'd0;\n            for (i = 0; i < 24; i = i + 1) begin\n                queue[i] <= 8'd0;\n                dist_queue[i] <= 5'd0;\n            end\n        end else begin\n            current_state <= next_state;\n            case (current_state)\n                STATE_IDLE: begin\n                    done <= 1'b0;\n                    error <= 1'b0;\n                    if (start) next_state <= STATE_INIT;\n                end\n\n                STATE_INIT: begin\n                    head <= 5'd0;\n                    tail <= 5'd1;\n                    queue[0] <= initial_perm;\n                    dist_queue[0] <= 5'd0;\n                    visited <= 256'd1 << initial_perm;\n                    current_perm <= initial_perm;\n                    distance_reg <= 5'd0;\n                    min_swaps_reg <= 5'd31;\n                    next_state <= STATE_DEQUEUE;\n                end\n\n                STATE_DEQUEUE: begin\n                    swap_counter <= 3'd0;\n                    if (fifo_empty) begin\n                        next_state <= STATE_ERROR;\n                    end else begin\n                        current_perm <= queue[head];\n                        distance_reg <= dist_queue[head];\n                        head <= head + 5'd1;\n                        next_state <= STATE_CHECK;\n                    end\n                end\n\n                STATE_CHECK: begin\n                    if (current_perm == 8'h6C) begin\n                        next_state <= STATE_DONE;\n                        min_swaps_reg <= distance_reg;\n                    end else begin\n                        next_state <= STATE_PROCESS_SWAP;\n                    end\n                end\n\n                STATE_PROCESS_SWAP: begin\n                    if (swap_counter < num_swaps) begin\n                        new_perm <= perform_swap(current_perm, swaps[swap_counter*4 +3 -:2], swaps[swap_counter*4 +1 -:2]);\n                        next_state <= STATE_NEXT_SWAP;\n                    end else begin\n                        next_state <= STATE_DEQUEUE;\n                    end\n                end\n\n                STATE_NEXT_SWAP: begin\n                    if (swap_counter < num_swaps) begin\n                        if (!visited[new_perm]) begin\n                            visited <= visited | (1 << new_perm);\n                            queue[tail] <= new_perm;\n                            dist_queue[tail] <= distance_reg + 5'd1;\n                            tail <= tail + 5'd1;\n                        end\n                        swap_counter <= swap_counter + 3'd1;\n                        next_state <= STATE_PROCESS_SWAP;\n                    end else begin\n                        next_state <= STATE_DEQUEUE;\n                    end\n                end\n\n                STATE_DONE: begin\n                    min_swaps <= min_swaps_reg;\n                    done <= 1'b1;\n                    next_state <= STATE_IDLE;\n                end\n\n                STATE_ERROR: begin\n                    error <= 1'b1;\n                    next_state <= STATE_IDLE;\n                end\n\n                default: next_state <= STATE_IDLE;\n            endcase\n        end\n    end\n\n    function [7:0] perform_swap;\n        input [7:0] perm;\n        input [1:0] pos1, pos2;\n        reg [1:0] temp1, temp2;\n        reg [7:0] result;\n        begin\n            temp1 = perm[pos1*2 +:2];\n            temp2 = perm[pos2*2 +:2];\n            result = perm;\n            result[pos1*2 +:2] = temp2;\n            result[pos2*2 +:2] = temp1;\n            perform_swap = result;\n        end\n    endfunction\nendmodule